        String base64urlChars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
        StringBuilder passcodeBuilder = new StringBuilder(21);
        java.security.SecureRandom random = new java.security.SecureRandom();
        for (int i = 0; i < 21; i++) {
            passcodeBuilder.append(base64urlChars.charAt(random.nextInt(base64urlChars.length())));
        }
        String passcode = passcodeBuilder.toString();

        // Constructor: SignifyClient(url, bran, tier, bootUrl, externalModules)
        SignifyClient client = new SignifyClient(keriaAdminUrl, passcode, null, keriaBootUrl, null);
        log.info("Signify client created with passcode: " + passcode);

        // Boot the agent in KERIA (creates agent if it doesn't exist)
