        HabState result = null;
        for (int i = 0; i < 20; i++) {
            try {
                result = client.identifiers().get(localName).orElse(null);
                if (result != null) {
                    break;
                }
            } catch (Exception e) {
                // Identifier not yet available, wait and retry
            }
            TimeUnit.SECONDS.sleep(1);
        }

        if (result == null) {
            throw new RuntimeException("Identifier was not anchored in time");
        }

        // ------------------------------------------------------------
        // 6. Extract and return the AID
        // ------------------------------------------------------------
        // In KERI, "i" is the identifier prefix (AID)
